// JOIN the 4 input tabs on store_id + sku_id, then add category-cohort stats.
// Thresholds are loaded directly from Config & Constants.
const cfg = $('Set Configuration Constants').first().json;
const n = (v, d = 0) => { const x = Number(v); return Number.isFinite(x) ? x : d; };
const asOf = (cfg.as_of_date && String(cfg.as_of_date).trim()) || $now.toFormat('yyyy-MM-dd');
const key = (r) => `${String(r.store_id).trim()}|${String(r.sku_id).trim()}`;
const rows = (name) => $(name).all().map(i => i.json);

const catalog = new Map(rows('Read Catalog').map(r => [String(r.sku_id).trim(), r]));
const sales   = new Map(rows('Read Sales Rollup').map(r => [key(r), r]));
const inv     = new Map(rows('Read Inventory').map(r => [key(r), r]));
const plano   = rows('Read Planogram');

// chain-wide median price per category_l2 + pack_size ("same size/variant")
const priceGroups = {};
for (const c of catalog.values()) (priceGroups[`${c.category_l2}|${c.pack_size}`] ||= []).push(n(c.mrp));
const median = (a) => { const s = [...a].sort((x, y) => x - y), m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };

// 1) join
const joined = [];
for (const p of plano) {
  const c = catalog.get(String(p.sku_id).trim());
  if (!c) continue;                       // SKU not in catalog -> skip (cannot price it)
  const s = sales.get(key(p)) || {};
  const i = inv.get(key(p)) || {};
  joined.push({
    as_of_date: asOf, store_id: String(p.store_id).trim(), sku_id: String(p.sku_id).trim(),
    product_name: c.product_name, brand: c.brand, category_l1: c.category_l1, category_l2: c.category_l2, pack_size: c.pack_size,
    mrp: n(c.mrp), cost_price: n(c.cost_price), min_margin_threshold: n(c.min_margin_threshold), shelf_life_days: n(c.shelf_life_days),
    units_30d: n(s.units_30d), units_prev_30d: n(s.units_prev_30d), units_90d: n(s.units_90d), revenue_30d: n(s.revenue_30d),
    last_sale_date: s.last_sale_date || '', discount_applied_30d: s.discount_applied_30d || 'NO',
    total_on_hand: n(i.total_on_hand), shelf_units: n(i.shelf_units), backroom_units: n(i.backroom_units),
    earliest_batch_expiry: i.earliest_batch_expiry || '',
    zone_tier: p.zone_tier, aisle: p.aisle, bay: p.bay, shelf: p.shelf,
    facing_count: n(p.facing_count), days_in_current_zone: n(p.days_in_current_zone),
    cat_median_price: median(priceGroups[`${c.category_l2}|${c.pack_size}`] || [n(c.mrp)]),
  });
}

// 2) category cohort per store + category_l2
const cohort = {};
for (const r of joined) {
  const g = (cohort[`${r.store_id}|${r.category_l2}`] ||= { u: 0, p: 0, n: 0 });
  g.u += r.units_30d; g.p += r.units_prev_30d; g.n += 1;
}
// 3) best non-prime SKU per cohort = the replacement candidate for freed prime space
const best = {};
for (const r of joined) {
  if (r.zone_tier === 'PRIME_EYE_LEVEL') continue;
  const k = `${r.store_id}|${r.category_l2}`;
  if (!best[k] || r.units_30d > best[k].units_30d) best[k] = r;
}
return joined.map(r => {
  const k = `${r.store_id}|${r.category_l2}`, g = cohort[k], b = best[k];
  return { json: { ...r,
    cat_sku_count: g.n, cat_units_30d: g.u, cat_avg_units_30d: Math.round(g.u / g.n * 100) / 100,
    cat_growth_pct: g.p > 0 ? Math.round((g.u - g.p) / g.p * 1000) / 1000 : 0,
    replacement_sku: b ? b.sku_id : '', replacement_name: b ? b.product_name : '', replacement_units_30d: b ? b.units_30d : 0 } };
});

