parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "final_action": {
      "type": "string",
      "enum": [
        "DEMOTE_AND_LIQUIDATE",
        "TEST_PRICE_REDUCTION",
        "RELOCATE_SECONDARY",
        "DELIST_CANDIDATE",
        "KEEP_MONITOR"
      ]
    },
    "agrees_with_rule": {
      "type": "boolean",
      "description": "true if final_action equals rule_action"
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "new_price": {
      "type": "number",
      "description": "Shelf price after action. Equal to mrp when no price change."
    },
    "target_zone": {
      "type": "string",
      "enum": [
        "PRIME_EYE_LEVEL",
        "REACH",
        "BOTTOM",
        "ENDCAP",
        "ENDCAP_SECONDARY",
        "CLEARANCE_BIN",
        "BACKROOM"
      ]
    },
    "target_facings": {
      "type": "integer",
      "minimum": 0,
      "maximum": 6
    },
    "move_units": {
      "type": "integer",
      "minimum": 0
    },
    "replacement_sku": {
      "type": "string",
      "description": "Copied from context or empty string"
    },
    "review_in_days": {
      "type": "integer",
      "minimum": 7,
      "maximum": 30
    },
    "reasoning": {
      "type": "string"
    },
    "store_note": {
      "type": "string"
    }
  },
  "required": [
    "final_action",
    "agrees_with_rule",
    "confidence",
    "new_price",
    "target_zone",
    "target_facings",
    "move_units",
    "replacement_sku",
    "review_in_days",
    "reasoning",
    "store_note"
  ],
  "additionalProperties": false
}
